mapper.select:
SELECT s.id, s.stocktake_no, s.warehouse_id, s.status, s.remark, s.confirmed_at, s.operator, s.version, s.created_at, s.updated_at, w.warehouse_code, w.name AS warehouse_name FROM inventory_stocktake s LEFT JOIN warehouse w ON w.id = s.warehouse_id WHERE s.deleted = FALSE
AND s.warehouse_id IN #{scopeId}
AND FALSE
AND s.stocktake_no ILIKE CONCAT('%', #{query.stocktakeNo}, '%')
AND s.warehouse_id = #{query.warehouseId}
AND s.status = #{query.status}
ORDER BY s.created_at DESC, s.id DESC
